import json
from openai import OpenAI
import os
from tqdm import tqdm
import argparse


# ================ Evaluate ================
def evaluate_answer(question, gold_answer, predicted_answer):
    system_prompt = (
        "You are an expert evaluator on natural sciences, such as hurricanes, geography, "
        "aging dams, compound flooding, and coastal hazards. Your task is to assess the "
        "predicted answer generated by AI models compared to the gold (reference) answer. "
        "Please evaluate the predicted answer on correctness and completeness. "
        "For the given question, evaluate using two criteria:\n\n"
        "1. Correctness (0 or 1):\n"
        "- Score 1 if the predicted answer is generally accurate and aligns with the key points in the reference answer.\n"
        "- Score 0 if it has factual errors or misrepresents key information.\n\n"
        "2. Completeness (0 or 1):\n"
        "- Score 1 if the predicted answer covers the main points present in the reference answer.\n"
        "- Score 0 if it misses essential information or fails to address the core of the question.\n\n"
        "Output your evaluation in the following JSON format:\n"
        '{"correctness": int, "completeness": int, "explanation": "your brief explanation"}'
    )

    user_prompt = (
        f"Question: {question}\n\n"
        f"Gold Answer: {gold_answer}\n\n"
        f"Predicted Answer: {predicted_answer}\n\n"
        "Please evaluate the predicted answer based on correctness and completeness, "
        "and respond ONLY with the JSON object."
    )

    client = OpenAI()
    response = client.chat.completions.create(
        model="gpt-4o",
        messages=[
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
        temperature=0,
    )

    reply = response.choices[0].message.content

    try:
        result = json.loads(reply.strip())
    except json.JSONDecodeError:
        print("Failed to parse JSON from model output. Raw output:\n", reply)
        result = {"correctness": -1, "completeness": -1, "explanation": "Parse error"}

    return result


# ================ Load Dataset ================
def load_dataset(data_path: str):
    if not os.path.exists(data_path):
        raise FileNotFoundError(f"LLM output file not found: {data_path}")
    if data_path.endswith(".json"):
        with open(data_path, "r", encoding="utf-8") as f:
            return json.load(f)
    else:
        raise ValueError("Unsupported file format. Use JSON only for now.")


# ================ Argument Parser ================
def parse_args():
    parser = argparse.ArgumentParser(description="LLM-as-judge evaluation for QA models.")
    parser.add_argument(
        "--data",
        type=str,
        required=True,
        choices=["hurricane", "geography", "aging_dam", "compound_flooding"],
        help="Dataset name.",
    )
    parser.add_argument(
        "--model",
        type=str,
        required=True,
        choices=["gpt-4", "gpt-4o", "gpt-3.5-turbo", "deepseek", "llama3", "llama4", "gemma", "qwen"],
        help="Model name used in the output file path.",
    )
    parser.add_argument(
        "--retrieval_method",
        type=str,
        required=True,
        choices=[
            "hypercube",            # unimodal hypercube
            "hypercube_mm",         # multimodal hypercube (your new one)
            "semantic",
            "union",
            "hipporag",
            "contriever",
            "bm25",
            "graphrag",
            "none",
        ],
        help="Retrieval method used to generate the outputs.",
    )
    return parser.parse_args()


# ================ Main Function ================
def main():
    args = parse_args()

    # -------- Resolve output file path based on retrieval_method --------
    if args.retrieval_method == "none":
        # No retrieval baseline
        llm_output_dir = f"output/{args.data}/{args.model}/llm_output_no_rag.json"
    elif args.retrieval_method == "bm25":
        llm_output_dir = f"output/{args.data}/{args.model}/llm_output_bm25.json"
    elif args.retrieval_method == "contriever":
        llm_output_dir = f"output/{args.data}/{args.model}/llm_output_semantic_contriever.json"
    elif args.retrieval_method == "graphrag":
        llm_output_dir = f"output/{args.data}/{args.model}/llm_output_graphrag.json"
    elif args.retrieval_method == "hipporag":
        llm_output_dir = f"output/{args.data}/{args.model}/llm_output_hipporag.json"
    elif args.retrieval_method == "hypercube_mm":
        # Your multimodal hypercube file naming for compound_flooding:
        #   output/compound_flooding/gpt-4o/compound_flooding_gpt-4o_hypercube_multimodal.json
        llm_output_dir = (
            f"output/{args.data}/{args.model}/"
            f"{args.data}_{args.model}_hypercube_multimodal.json"
        )
    else:
        # Default pattern for unimodal hypercube / semantic / union / etc.
        # e.g., llm_output_hypercube_nv.json, llm_output_semantic_nv.json
        llm_output_dir = f"output/{args.data}/{args.model}/llm_output_{args.retrieval_method}_nv.json"

    print(f"Loading LLM outputs from: {llm_output_dir}")
    qa_samples = load_dataset(llm_output_dir)
    num_samples = len(qa_samples)
    print(f"Loaded {num_samples} samples.\n")

    # === Evaluate each pair ===
    total_correct, total_complete = 0, 0
    results = []

    for sample in tqdm(qa_samples, desc="Evaluating with LLM-as-judge"):
        # Support both schemas:
        #  - "gold_answer" / "predicted_answer"  (your hurricane code)
        #  - "answer_gold" / "answer_pred"      (your CF RAG code)
        question = sample.get("question", "")

        gold_answer = (
            sample.get("gold_answer")
            if sample.get("gold_answer") is not None
            else sample.get("answer_gold", "")
        )
        predicted_answer = (
            sample.get("predicted_answer")
            if sample.get("predicted_answer") is not None
            else sample.get("answer_pred", "")
        )

        if not question or gold_answer is None or predicted_answer is None:
            print("Warning: missing fields in sample, skipping:", sample)
            continue

        eval_result = evaluate_answer(question, gold_answer, predicted_answer)
        sample.update(eval_result)
        results.append(sample)

        total_correct += eval_result.get("correctness", 0)
        total_complete += eval_result.get("completeness", 0)

    if results:
        avg_correct = total_correct / len(results)
        avg_complete = total_complete / len(results)
    else:
        avg_correct = avg_complete = 0.0

    print(
        f"\nTotal evaluated samples: {len(results)} "
        f"(original {num_samples})"
    )
    print(f"Average correctness : {avg_correct:.4f}")
    print(f"Average completeness: {avg_complete:.4f}")

    # If you want to save judged outputs, uncomment:
    # out_name = f"judged_{args.data}_{args.model}_{args.retrieval_method}.json"
    # out_path = os.path.join("output", args.data, args.model, out_name)
    # os.makedirs(os.path.dirname(out_path), exist_ok=True)
    # with open(out_path, "w", encoding="utf-8") as f:
    #     json.dump(results, f, indent=2, ensure_ascii=False)
    # print(f"\nSaved detailed judge results to: {out_path}")


if __name__ == "__main__":
    main()
